	.byte	vib0-vib0+0
	.byte	vib1-vib0+1, vib1-vib0+2, vib1-vib0+3, vib1-vib0+0
	.byte	vib2-vib0+1, vib2-vib0+2, vib2-vib0+3, vib2-vib0+4, vib2-vib0+5, vib2-vib0+0
