	nop
	jmp	cmd7
.endif
.endif	;</2>
.else	;<1ELSE> ne, nejsou tam vubec zadne jine commandy nez COMMAND 0, takze se nezkompiluje nic az po cmd0
	;jeste musi pridat naplneni trackn_command,x ,pokud je to potreba
.if FEAT_FILTER||FEAT_BASS16
	lda	reg2
	sta	trackn_command,x	;pouziva se jen pro filtrovani a/nebo 16bit bassy
.endif
