	lda	(nr),y
	clc
	adc	trackn_tablenote,x	;zde jako frekvence
	jmp	cmd5ax
.endif	;FEAT_TABLETYPE
cmd5a1 = *
	lda	trackn_note,x
	clc
	adc	trackn_tablenote,x
	cmp	#61
