SetPokey = *
;
.if STEREOMODE=1	;* L1 L2 L3 L4 R1 R2 R3 R4
;zapis do dvou POKEYu stereo (nejdriv vzdy pravy a pak okamzite levy registr)
;
	ldy	#$ff	;parametr je prepisovan
v_audctl2 = *-1
;AUDF0
	lda	trackn_audf+0+4
	ldx	trackn_audf+0
xstastx01 = *
	sta	$d210
	stx	$d200
;AUDC0
	lda	trackn_audc+0+4
	ldx	trackn_audc+0
xstastx02 = *
	sta	$d211
	stx	$d201
;AUDF1
	lda	trackn_audf+1+4
	ldx	trackn_audf+1
xstastx03 = *
	sta	$d212
	stx	$d202
;AUDC1
	lda	trackn_audc+1+4
	ldx	trackn_audc+1
xstastx04 = *
	sta	$d213
	stx	$d203
;AUDF2
	lda	trackn_audf+2+4
	ldx	trackn_audf+2
xstastx05 = *
	sta	$d214
	stx	$d204
;AUDC2
	lda	trackn_audc+2+4
	ldx	trackn_audc+2
xstastx06 = *
	sta	$d215
	stx	$d205
;AUDF3
	lda	trackn_audf+3+4
	ldx	trackn_audf+3
xstastx07 = *
	sta	$d216
	stx	$d206
;AUDC3
	lda	trackn_audc+3+4
	ldx	trackn_audc+3
xstastx08 = *
	sta	$d217
	stx	$d207
;AUDCTL
	lda	#$ff	;parametr je prepisovan
v_audctl = *-1
;Y bylo nastaveno kus nahore
xstysta01 = *
	sty	$d218
	sta	$d208
;
.elseif STEREOMODE=0	;* L1 L2 L3 L4
;zapis do POKEYe mono - jen leva strana
;
	ldy	#$ff	;parametr je prepisovan
v_audctl = *-1
;
	lda	trackn_audf+0
	ldx	trackn_audc+0
	sta	$d200
	stx	$d201
;
	lda	trackn_audf+1
	ldx	trackn_audc+1
	sta	$d200+2
	stx	$d201+2
;
	lda	trackn_audf+2
	ldx	trackn_audc+2
	sta	$d200+4
	stx	$d201+4
;
	lda	trackn_audf+3
	ldx	trackn_audc+3
	sta	$d200+6
	stx	$d201+6
;
	sty	$d208
;
.elseif STEREOMODE=2	;* L1 R2 R3 L4
;zapis do L1 R2 R3 L4
;
	ldy	#$ff	;parametr je prepisovan
v_audctl = *-1
;
	lda	trackn_audf+0
	ldx	trackn_audc+0
	sta	$d200
	stx	$d201
	sta	$d210	;frekvenci i do praveho (kdyby R2 hralo 16bit bass 2+1)
;
	lda	trackn_audf+1
	ldx	trackn_audc+1
	sta	$d210+2
	stx	$d211+2
;
	lda	trackn_audf+2
	ldx	trackn_audc+2
	sta	$d210+4
	stx	$d211+4
	sta	$d200+4	;frekvenci i do leveho (kdyby L1 hralo filter 1+3 nebo kdyby L4 hralo 16bit bass 4+3)
;
	lda	trackn_audf+3
	ldx	trackn_audc+3
	sta	$d200+6
	stx	$d201+6
	sta	$d210+6	;frekvenci i do praveho (kdyby R2 hralo filter 2+4)
;
	sty	$d218
	sty	$d208
;
.elseif STEREOMODE=3	;* L1 L2 R3 R4
;zapis do L1 L2 R3 R4
;
	ldy	#$ff	;parametr je prepisovan
v_audctl = *-1
;
	lda	trackn_audf+0
	ldx	trackn_audc+0
	sta	$d200
	stx	$d201
;
	lda	trackn_audf+1
	ldx	trackn_audc+1
	sta	$d200+2
	stx	$d201+2
;
	lda	trackn_audf+2
	ldx	trackn_audc+2
	sta	$d210+4
	stx	$d211+4
	sta	$d200+4	;frekvenci i do leveho (kdyby L1 hralo filter 1+3)
;
	lda	trackn_audf+3
	ldx	trackn_audc+3
	sta	$d210+6
	stx	$d211+6
	sta	$d200+6	;frekvenci i do leveho (kdyby L2 hralo filter 2+4)
;
	sty	$d218
	sty	$d208
;
.endif
;
	rts
